def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 > v1:
        result = 2019
    elif v1 > v2:
        result = 2018
    else:
        result = None

    return {
        "value": result,
        "trace": {
            "v1_2018": v1,
            "v2_2019": v2,
            "comparison": "2019 larger" if v2 > v1 else ("2018 larger" if v1 > v2 else "equal"),
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
